<script setup>
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue';
import { Button, Cell, CellGroup, Collapse, CollapseItem, Field, Form, Radio, RadioGroup, Search, Tab, Tabs, Tag,Popup,Picker } from 'vant';
import StudentCourseSettings from './StudentCourseSettings.vue';
import 'vant/es/button/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';import 'vant/es/collapse/style';import 'vant/es/collapse-item/style';import 'vant/es/field/style';import 'vant/es/form/style';import 'vant/es/radio/style';import 'vant/es/radio-group/style';import 'vant/es/search/style';import 'vant/es/tabs/style';import 'vant/es/tab/style';import 'vant/es/tag/style';
const props=defineProps({controller:{type:Object,required:true}}),m=shallowRef(props.controller.model),a=props.controller.actions;
const unsubscribe=props.controller.subscribe(value=>m.value=value);
onBeforeUnmount(unsubscribe);
const recallAnswer=ref(''),quizAnswers=ref([]),expanded=ref([]),unitPicker=ref(false),filterPicker=ref(false);
const filters=[{text:'全部词条',value:'all'},{text:'必会',value:'required'},{text:'待掌握',value:'pending'},{text:'已达标',value:'mastered'},{text:'选学',value:'optional'}];
const mainTab=computed(()=>['word','recall','words'].includes(m.value.view)?'words':['lesson','quiz','lessons'].includes(m.value.view)?'lessons':m.value.view);
const filtered=computed(()=>{const term=m.value.query.trim().toLowerCase();return m.value.words.filter(w=>(!term||w.word.toLowerCase().includes(term)||w.meaning.includes(term))&&(m.value.filter==='all'||m.value.filter==='optional'&&w.optional||m.value.filter==='required'&&!w.optional||m.value.filter==='mastered'&&m.value.wordPassed[w.id]||m.value.filter==='pending'&&!w.optional&&!m.value.wordPassed[w.id]));});
const feynman=computed(()=>m.value.state?.feynman[m.value.lesson?.id]||{}),last=computed(()=>feynman.value.attempts?.at(-1));
const nextLabel=computed(()=>m.value.words.indexOf(m.value.word)<m.value.words.length-1?'下一个单词':'返回本单元');
watch(()=>[m.value.view,m.value.lesson?.id],()=>{quizAnswers.value=[];recallAnswer.value='';});
function submitRecall(){const before=m.value.stage;a.submitRecall(recallAnswer.value);if(before==='recall'||m.value.stage!==before)recallAnswer.value='';}
function switchUnit({selectedValues}){unitPicker.value=false;location.assign(new URL(selectedValues[0],location.href).href);}
</script>
<template>
 <nav class="course-return-nav"><Button tag="a" href="units.html?subject=english&term=upper" data-growing-back>← 返回上一级</Button></nav>
 <main class="student-english-course">
  <template v-if="m.kind==='error'"><h1>{{ m.title }}</h1><p role="status">{{ m.message }}</p><a :href="m.backHref">返回英语目录</a></template>
  <template v-else>
   <header class="student-english-header unit-header"><div><p class="eyebrow">译林版 · 2025秋新教材 · 八年级上册</p><h1>Unit {{ m.unit.number }}<br>{{ m.unit.title }}</h1><p class="muted">{{ m.unit.summary }}</p><a href="units.html?subject=english&term=upper">← 英语目录</a></div><div class="unit-select"><label>切换单元</label><Cell :value="'Unit '+m.unit.number+' · '+m.unit.title" is-link clickable @click="unitPicker=true"/></div></header>
   <nav class="student-english-links tabs" aria-label="英语学习工具"><Button v-for="item in [{id:'words',text:'单词与默写'},{id:'lessons',text:'阅读与语法'},{id:'feynman',text:'概念复述'}]" :key="item.id" :aria-current="mainTab===item.id?'page':undefined" @click="a.navigate(item.id)">{{item.text}}</Button><Button :url="'english-sentence-demo.html?unit='+m.unit.id">句子闯关</Button><Button :url="'english-resources.html?unit='+m.unit.id">试卷</Button></nav>
   <p v-if="m.notice" role="status" aria-live="polite" class="student-english-notice">{{ m.notice }}</p>
   <section v-if="m.view==='words'" class="word-library" aria-label="本单元词表"><h2>{{ m.words.length }}个单词与短语（{{ m.passed }}/{{ m.words.length }}）</h2><div class="word-tools"><Field :model-value="m.query" placeholder="输入英文或中文" aria-label="搜索词条或释义" @update:model-value="a.query"/><Cell :value="filters.find(f=>f.value===m.filter)?.text" is-link clickable @click="filterPicker=true"/></div><div class="student-english-grid word-grid"><article v-for="w in filtered" :key="w.id" class="word-card" :class="{'word-card-pending':!w.optional&&!m.wordPassed[w.id]}"><Tag :class="{optional:w.optional}">{{ w.optional?'★ 只要求会读、听懂':m.wordPassed[w.id]?'默写达标':'待掌握' }}</Tag><h3><Button class="word-card-link" @click="a.word(w.id)">{{w.word}}</Button></h3><p>{{w.meaning}}</p></article></div><p v-if="!filtered.length">没有符合条件的词条，请调整搜索或筛选。</p></section>
   <section v-else-if="m.view==='word'" class="student-english-panel"><Tag>{{ m.word.optional?'★ 选学词条':m.wordFullyPassed?'✓ 拼写与词义词类均已掌握':m.wordPassed[m.word.id]?'✓ 历史默写达标 · 可补测口述':'必会词条' }}</Tag><h2 lang="en">{{ m.word.word }}</h2><template v-if="m.hideWordMeaning"><p>七次默写已完成，词义与词类已隐藏，请继续验证。</p></template><template v-else><p>{{ m.word.meaning }}</p><p v-if="m.description.plurals.length">复数：{{ m.description.plurals.join(' / ') }}</p></template><div class="student-english-actions"><Button @click="a.speak(false)">听发音</Button><Button type="primary" @click="a.recall">{{ m.state.words[m.word.id]?.practice?'继续本词验证':'开始闭卷默写 · 7次' }}</Button><Button @click="a.navigate('words')">返回词表</Button></div></section>
   <section v-else-if="m.view==='recall' && m.run" class="student-english-panel" :data-stage="m.stage"><p>拼写 {{ m.run.answers.length }}/7</p><template v-if="m.stage!=='oral'"><h2>{{ m.stage==='recall'?m.word.meaning:m.word.word }}</h2><p>{{ m.stage==='recall'?'连续正确默写七次，答错后重新累计。':'请默写这个词的复数形式。中文释义已隐藏。' }}</p><Form @submit="submitRecall"><Field v-model="recallAnswer" :label="m.stage==='recall'?'第 '+(m.run.answers.length+1)+'/7 次':'复数形式'" :aria-label="m.stage==='recall'?'英文默写':'复数形式'" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" maxlength="140" :rules="[{required:true,message:'请先填写答案'}]"/><Button type="primary" native-type="submit">{{ m.stage==='recall'?'提交默写':'确认复数' }}</Button></Form><p v-if="m.failedAnswer" class="student-english-gap">刚才拼写有误，你写的是：{{ m.failedAnswer }}；正确词条：{{ m.word.word }}。请看清后重新默写。</p></template><template v-else><h2 lang="en">{{ m.word.word }}</h2><Form @submit="a.gradeOral"><Field :model-value="m.run.draft" type="textarea" rows="4" label="词义和词类口述" maxlength="2000" :disabled="m.busy" :readonly="m.completed" :rules="[{required:true,message:'请先说出词类以及中文意思'}]" @update:model-value="a.oralDraft"/><div class="student-english-actions"><Button type="primary" native-type="submit" :disabled="m.busy||m.completed" :loading="m.busy">提交</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button></div></Form><section v-if="m.run.oral" aria-label="批改结果"><p>拼写：✓　词义：{{ m.run.oral.meaningPassed?'✓':'✗' }}　词类：{{ m.run.oral.posPassed?'✓':'✗' }}</p><p>{{ m.run.oral.feedback }}</p><ul class="student-english-gap"><li v-for="(error,i) in m.run.oral.errors" :key="i">{{ error }}</li></ul><div class="student-english-actions"><Button v-if="!m.oralSaved || m.run.oral.meaningPassed&&m.run.oral.posPassed&&!m.run.oral.errors.length&&!m.completed" @click="a.retryOralSave">重试保存</Button><Button :disabled="m.busy||!m.oralSaved||m.run.oral.meaningPassed&&m.run.oral.posPassed&&!m.run.oral.errors.length&&!m.completed" @click="a.nextWord">{{ nextLabel }}</Button></div></section></template><Button @click="a.navigate('word')">返回词条</Button></section>
   <section v-else-if="m.view==='lessons'"><h2>阅读导学与语法微课</h2><CellGroup><Cell v-for="l in m.lessons" :key="l.id" :title="l.title" :label="m.lessonPassed[l.id]?'✓ 检测达标':'待检测'" is-link @click="a.lesson(l.id)"/></CellGroup></section>
   <article v-else-if="m.view==='lesson'" class="student-english-panel"><p>Unit {{ m.unit.number }} · 阅读与语法</p><h2>{{ m.lesson.title }}</h2><ul><li v-for="(point,i) in m.lesson.points" :key="i">{{ point }}</li></ul><p class="student-english-muted">示例</p><blockquote lang="en">{{ m.lesson.example }}</blockquote><div class="student-english-actions"><Button @click="a.speak(true)">听读示例</Button><Button type="primary" @click="a.quiz">收起讲解，开始3题检测</Button><Button @click="a.navigate('lessons')">返回微课列表</Button></div></article>
   <section v-else-if="m.view==='quiz'&&m.attempt" class="student-english-panel"><template v-if="m.attempt.result"><h2>{{ m.attempt.result.saved?'3/3正确，已达标':m.attempt.result.correct===3?'3/3正确，记录尚未保存':'本轮 '+m.attempt.result.correct+'/3，继续练习' }}</h2><p>本轮检测{{ m.attempt.result.saved?'已保存。':'未计入掌握。' }}</p><ol><li v-for="(q,i) in m.lesson.questions" :key="i"><strong>{{ q.prompt }}</strong><p>你的答案：{{ m.attempt.result.answers[i] }}</p><p>正确答案：{{ q.answer }}</p><p>{{ q.explain }}</p></li></ol><div class="student-english-actions"><Button @click="a.quiz">再测一次</Button><Button @click="a.lesson(m.lesson.id)">回看讲解</Button><Button @click="a.navigate('lessons')">返回微课列表</Button></div></template><template v-else><h2>{{ m.lesson.title }}</h2><p>请独立作答。提交后可看逐题解析，未达标可以回看讲解再测。</p><Form @submit="a.submitQuiz(m.lesson.questions.map((_,i)=>quizAnswers[i]))"><Field v-for="(q,i) in m.lesson.questions" :key="i" :name="'q'+i" :label="(i+1)+'. '+q.prompt" :model-value="quizAnswers[i]" :rules="[{required:true,message:'请选择答案'}]"><template #input><RadioGroup v-model="quizAnswers[i]"><Radio v-for="(option,j) in m.attempt.options[i]" :key="option" :name="option">{{ String.fromCharCode(65+j) }}. {{ option }}</Radio></RadioGroup></template></Field><Button type="primary" native-type="submit">提交检测</Button></Form></template></section>
   <section v-else-if="m.view==='feynman'" class="student-english-panel"><h2>用自己的话，讲明白一个概念</h2><Collapse v-model="expanded"><CollapseItem :title="'选择概念：'+m.lesson.title" name="concept"><Cell v-for="l in m.lessons" :key="l.id" :title="l.title+(m.feynmanPassed[l.id]?' · 已掌握':'')" is-link @click="a.feynmanLesson(l.id)"/></CollapseItem></Collapse><p>请解释“{{ m.lesson.title }}”的意思、使用条件，举一个自己的例子，并指出一个容易混淆的地方。可用中文讲解并用英文举例。</p><Form @submit="a.gradeFeynman"><Field :model-value="feynman.draft||''" type="textarea" rows="6" label="你的复述" maxlength="5000" :disabled="m.busy" :rules="[{validator:value=>value?.trim().length>=5,message:'请至少写下5个字的解释和例子'}]" @update:model-value="a.feynmanDraft"/><div class="student-english-actions"><Button type="primary" native-type="submit" :disabled="m.busy" :loading="m.busy">AI评阅概念复述</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button><Button @click="a.navigate('settings')">AI连接设置</Button></div></Form><section v-if="m.validExplanation&&last"><h3>{{ last.score }}/10 · {{ last.score>=8&&!last.criticalErrors.length?'本次概念解释达标':'继续补充后重试' }}</h3><p>{{ last.feedback }}</p><h4 v-if="last.gaps?.length">待巩固与遗漏</h4><ul class="student-english-gap"><li v-for="(gap,i) in last.gaps||[]" :key="i">{{ gap }}</li></ul><p v-if="last.criticalErrors.length" class="student-english-gap">核心错误：{{ last.criticalErrors.join('；') }}</p></section></section>
   <section v-else-if="m.view==='doubts'" class="student-english-panel"><h2>我有疑问 · Unit {{ m.unit.number }}</h2><Button @click="a.navigate('settings')">AI连接设置</Button><p>可问词义、语法、阅读或其他问题。</p><article v-for="(message,i) in m.doubt.messages" :key="i" class="student-english-message"><h3>{{ message.role==='user'?'我的问题':'老师的解释' }}</h3><p>{{ message.text }}</p></article><Form @submit="a.askDoubt"><Field :model-value="m.doubt.draft" type="textarea" rows="5" label="你的问题" maxlength="2000" :disabled="m.busy" :rules="[{required:true,message:'请先输入问题'}]" @update:model-value="a.doubtDraft"/><div class="student-english-actions"><Button type="primary" native-type="submit" :disabled="m.busy" :loading="m.busy">发送问题</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button></div></Form><p role="status" aria-live="polite">{{ m.doubtNotice }}</p></section>
   <StudentCourseSettings v-else-if="m.view==='settings'" :services="m.settings" @close="a.navigate('words')"/>
   <Popup v-model:show="unitPicker" position="bottom" round teleport="body"><Picker title="切换单元" :columns="m.units.map(u=>({text:'Unit '+u.number+' · '+u.title,value:u.entry}))" @confirm="switchUnit"><template #cancel><Button icon="cross" aria-label="关闭单元选择" @click="unitPicker=false"/></template></Picker></Popup>
   <Popup v-model:show="filterPicker" position="bottom" round teleport="body"><Picker title="词条筛选" :columns="filters" :model-value="[m.filter]" @confirm="({selectedValues})=>{filterPicker=false;a.filter(selectedValues[0])}"><template #cancel><Button icon="cross" aria-label="关闭词条筛选" @click="filterPicker=false"/></template></Picker></Popup>
  </template>
 </main>
</template>
